    @Autowired CatalogSetService service;@LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired JwtTokenProvider tokens;
    HttpClient client=HttpClient.newHttpClient();Map<String,JsonNode> evidence=new LinkedHashMap<>();
    record User(long id,String token){}
    User user(String role){long id=insert(jdbc,"INSERT INTO sys_user(username,password,real_name,role,status,token_version) VALUES (?,?,'合成B34HTTP用户',?,1,0)","b34http_"+UUID.randomUUID().toString().replace("-",""),"synthetic-not-login",role);return new User(id,tokens.generateToken(id,"synthetic",role,0L));}
    JsonNode http(String method,String path,JsonNode body,User user,int status)throws Exception{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api"+path));if(user!=null)b.header("Authorization","Bearer "+user.token());if(body!=null)b.header("Content-Type","application/json");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(write(body)));var response=client.send(b.build(),HttpResponse.BodyHandlers.ofString());assertEquals(status,response.statusCode(),response.body());JsonNode parsed=read(response.body());assertEquals(1,parsed.path("data").path("schemaVersion").asInt());evidence.put(method+" "+path+" #"+evidence.size(),parsed);return parsed.path("data");}
    @Test void actualNetworkHttpPreviewCancelRecoveryConfirmPermissionsAndRoleRevocation()throws Exception{User admin=user("ADMIN"),clerk=user("LIBRARIAN"),reader=user("READER"),other=user("ADMIN");http("GET","/catalog-sets?unknown=1",null,null,403);http("GET","/catalog-sets/99999999",null,reader,403);http("POST","/catalog-sets/previews",obj("invalid",true),clerk,403);long book=insert(jdbc,"INSERT INTO book(isbn,title,stock_total,stock_available) VALUES (?, '合成HTTP套装成员',0,0)",UUID.randomUUID().toString().substring(0,20));JsonNode ctx=http("GET","/catalog-sets/books/contexts?bookId="+book,null,admin,200).path("records").get(0),ev=obj("kind","MANUAL_REVIEW","reference","合成HTTP逐边版权资料"),row=obj("bookId",book,"expectedBook",obj("revision",ctx.path("book").get("revision"),"attributeRevision",ctx.path("book").get("attributeRevision"),"digest",ctx.get("bookDigest"),"sourceDigest",ctx.path("source").get("digest")),"evidence",ev);ObjectNode n=obj("schemaVersion",1,"operationKey",UUID.randomUUID().toString(),"mode","MANUAL","reason","合成HTTP明确核对","operation","CREATE","clientRef","http_set","name","合成HTTP套装📚","note",null,"evidence",ev,"members",List.of(row));JsonNode p=http("POST","/catalog-sets/previews",n,admin,200);String path="/catalog-sets/requests/"+p.path("requestId").asLong();ObjectNode confirm=obj("schemaVersion",1,"operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest")),cancel=confirm.deepCopy().put("reason","EDIT");JsonNode cancelled=http("POST",path+"/cancel",cancel,admin,200);assertEquals("CANCELLED",cancelled.path("state").asText());assertEquals(cancelled,http("GET","/catalog-sets/requests/by-key?key="+p.path("operationKey").asText(),null,admin,200));assertEquals(cancelled,http("POST","/catalog-sets/previews",n,admin,200));http("POST",path+"/confirm",confirm,admin,409);n.put("operationKey",UUID.randomUUID().toString());JsonNode next=http("POST","/catalog-sets/previews",n,admin,200);String request="/catalog-sets/requests/"+next.path("requestId").asLong();ObjectNode key=obj("schemaVersion",1,"operationKey",next.get("operationKey"),"previewDigest",next.get("previewDigest"));JsonNode receipt=http("POST",request+"/confirm",key,admin,200);assertEquals(receipt,http("POST",request+"/confirm",key,admin,200));long set=receipt.path("result").path("set").path("setId").asLong();assertFalse(http("GET","/catalog-sets/"+set+"/members",null,clerk,200).toString().contains("evidence"));http("GET","/catalog-sets/"+set+"/maintenance-members",null,clerk,403);http("GET",request,null,other,403);assertEquals(0,http("GET","/catalog-sets/"+set+"/events",null,other,200).path("total").asLong());assertEquals(1,http("GET","/catalog-sets/"+set+"/events",null,admin,200).path("total").asLong());JsonNode maintenance=http("GET","/catalog-sets/"+set+"/maintenance-members?size=1&status=ALL",null,admin,200);assertEquals(1,maintenance.path("total").asLong());assertEquals(book,maintenance.path("records").get(0).path("book").path("book").path("bookId").asLong());assertEquals("NO_SOURCE",maintenance.path("records").get(0).path("book").path("source").path("markerState").asText());assertTrue(http("GET","/catalog-sets/"+set+"/maintenance-members?size=20&page=2&status=ALL",null,admin,200).path("records").isEmpty());assertEquals("SET_NOT_FOUND",http("GET","/catalog-sets/9007199254740991/maintenance-members?size=1",null,admin,404).path("reasonCode").asText());jdbc.update("UPDATE book SET deleted=1 WHERE id=?",book);assertTrue(http("GET","/catalog-sets/"+set+"/maintenance-members?size=20&status=ALL",null,admin,200).path("records").get(0).path("book").path("book").path("deleted").asBoolean());jdbc.update("UPDATE sys_user SET role='READER' WHERE id=?",admin.id());http("GET",request,null,admin,403);http("POST",request+"/confirm",key,admin,403);String dir=System.getProperty("b34.evidence.dir");if(dir!=null)Files.writeString(Path.of(dir,"actual-network-http.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("synthetic",true,"transport","Java HttpClient -> real TCP/Tomcat/JWT/current database role -> MySQL 8.0.44","responses",evidence)));}
    long sourceBook(String label,String suffix){return insert(jdbc,"INSERT INTO book(isbn,title,stock_total,stock_available) VALUES (?,?,0,0)",UUID.randomUUID().toString().substring(0,20),label+suffix);}
    long sourceRow(Long book,String text,List<Long> ids){String key="B34HTTP_"+UUID.randomUUID().toString().replace("-","");if(book!=null)jdbc.update("INSERT INTO book_copy(book_id,barcode,action_version) VALUES (?,?,7)",book,key);long id=insert(jdbc,"INSERT INTO legacy_record(source_system,record_type,source_key,book_id,details_json,display_name) VALUES ('huiben','BOOK',?,?,?,'合成B34HTTP固定路径来源')",key,book,text);ids.add(id);return id;}
    Object nullableText(Object value){return value==null?null:value.toString();}
    @Test void actualSourceHttpMatrixAndSameBatchWhitelistProjectionInputs()throws Exception{User admin=user("ADMIN");String label="B34_HTTP_SOURCE_"+UUID.randomUUID().toString().replace("-","");List<Long> records=new ArrayList<>();long none=sourceBook(label,"无来源"),valid=sourceBook(label,"有效"),conflict=sourceBook(label,"冲突"),overflow=sourceBook(label,"201条"),missing=sourceBook(label,"缺字段"),invalid=sourceBook(label,"无效根"),nonString=sourceBook(label,"非字符串");List<Long> books=List.of(none,valid,conflict,overflow,missing,invalid,nonString);jdbc.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,updated_at) VALUES (?,3,?,'MANUAL',CURRENT_TIMESTAMP)",valid,label+"展示名");sourceRow(valid,"{\"套装类型\":\"套装中单本\",\"无关字段\":\"不在白名单输出\"}",records);sourceRow(conflict,"{\"套装类型\":\"套装中单本\"}",records);sourceRow(conflict,"{\"套装类型\":null}",records);for(int i=0;i<201;i++)sourceRow(overflow,"{\"套装类型\":\"套装中单本\"}",records);sourceRow(missing,"{}",records);sourceRow(invalid,"not-json",records);sourceRow(nonString,"{\"套装类型\":{\"z\":1,\"a\":false}}",records);long orphan=sourceRow(null,"{\"套装类型\":\"套装中单本\"}",records);String query=books.stream().map(id->"bookId="+id).reduce((a,b)->a+"&"+b).orElseThrow();JsonNode contexts=http("GET","/catalog-sets/books/contexts?"+query,null,admin,200);assertEquals(books.size(),contexts.path("records").size());http("GET","/catalog-set-reviews?scope=ALL&size=100&keyword="+URLEncoder.encode(label,java.nio.charset.StandardCharsets.UTF_8),null,admin,200);List<String> keys=new ArrayList<>();books.forEach(id->keys.add("SET_SOURCE_BOOK:"+id));keys.add("SET_SOURCE_RECORD:"+orphan);for(String key:keys){int pages=key.equals("SET_SOURCE_BOOK:"+overflow)?3:1;for(int page=1;page<=pages;page++)http("GET","/catalog-set-reviews/sources?caseKey="+key+"&size=100&page="+page,null,admin,200);}boolean found=false;for(int page=1;;page++){JsonNode list=http("GET","/catalog-set-reviews?scope=ALL&bookDeleted=ALL&reason=ASSOCIATION_INVALID&size=100&page="+page,null,admin,200);for(JsonNode row:list.path("records"))if(row.path("caseKey").asText().equals("SET_SOURCE_RECORD:"+orphan))found=true;if(found||page>=list.path("pages").asInt())break;}assertTrue(found);
        List<Map<String,Object>> bookRows=jdbc.queryForList("SELECT b.id,b.isbn,b.title,b.deleted,b.catalog_set_book_revision,a.display_title_override,COALESCE(a.revision,0) AS attribute_revision FROM book b LEFT JOIN catalog_book_attribute a ON a.book_id=b.id WHERE b.id IN ("+placeholders(books.size())+") ORDER BY b.id",books.toArray());for(var row:bookRows)row.replaceAll((k,v)->nullableText(v));List<Map<String,Object>> sourceRows=new ArrayList<>();for(var row:jdbc.queryForList("SELECT r.* FROM ("+service.sources.rawSql()+") r WHERE r.id IN ("+placeholders(records.size())+") ORDER BY r.id",records.toArray())){String cell=row.get("cell_json")==null?"N":"H"+HexFormat.of().withUpperCase().formatHex(bytes(row.get("cell_json").toString()));sourceRows.add(new LinkedHashMap<>(Map.of("id",row.get("id").toString(),"system_hex",HexFormat.of().withUpperCase().formatHex(bytes(row.get("source_system").toString())),"type_hex",HexFormat.of().withUpperCase().formatHex(bytes(row.get("record_type").toString())),"source_key",row.get("source_key"),"key_hex",HexFormat.of().withUpperCase().formatHex(bytes(row.get("source_key").toString())),"root_kind",row.get("root_kind"),"present",row.get("present").toString(),"cell",cell)));sourceRows.get(sourceRows.size()-1).put("book_id",nullableText(row.get("book_id")));}List<Map<String,Object>> copies=jdbc.queryForList("SELECT c.id,c.book_id,HEX(c.barcode_key) AS key_hex,b.deleted FROM book_copy c LEFT JOIN book b ON b.id=c.book_id WHERE c.book_id IN ("+placeholders(books.size())+") ORDER BY c.id",books.toArray());for(var row:copies)row.replaceAll((k,v)->nullableText(v));String dir=System.getProperty("b34.evidence.dir");if(dir!=null){Files.writeString(Path.of(dir,"source-http-whitelist-inputs.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("synthetic",true,"fixtureBookIds",books,"fixtureRecordIds",records,"orphanCaseKey","SET_SOURCE_RECORD:"+orphan,"books",bookRows,"sources",sourceRows,"copies",copies)));Files.writeString(Path.of(dir,"actual-network-http-sources.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("synthetic",true,"transport","real TCP/Tomcat/JWT/MySQL; all source values are one fixed path projection","fixtureCaseKeys",keys,"responses",evidence)));}}

